parameters.jsCode:
const body = $('WhatsApp Webhook').item.json.body || $('WhatsApp Webhook').item.json || {};
let phone = '';
let text = '';
let messageId = '';
let contactName = '';
let messageType = 'none';
try {
  const value = body.entry[0].changes[0].value;
  const msg = value.messages ? value.messages[0] : null;
  if (msg) {
    phone = String(msg.from || '');
    messageId = String(msg.id || '');
    messageType = String(msg.type || 'unknown');
    if (msg.type === 'text' && msg.text) text = String(msg.text.body || '');
    else if (msg.type === 'button' && msg.button) text = String(msg.button.text || '');
    else if (msg.type === 'interactive' && msg.interactive) text = String((msg.interactive.button_reply && msg.interactive.button_reply.title) || (msg.interactive.list_reply && msg.interactive.list_reply.title) || '');
  }
  if (value.contacts && value.contacts[0] && value.contacts[0].profile) contactName = String(value.contacts[0].profile.name || '');
} catch (e) {
  phone = '';
}
const isMessage = !!phone && messageType !== 'none';
const unsupported = isMessage && !text;
return { json: { isMessage, unsupported, phone, text, messageId, contactName, messageType } };

const msg = $('Parse WhatsApp Message').first().json;
const cfg = $('Agent Config').first().json;
const turns = Number(cfg.HistoryTurns) || 10;
const rows = $input.all().map(i => i.json).filter(r => !r.error);
const mine = rows.filter(r => String(r.Phone || '') === msg.phone);
const recent = mine.slice(-turns);
const history = recent.map(r => (String(r.Direction || '') === 'in' ? 'Customer: ' : 'Agent: ') + String(r.Message || '')).join('\n');
const handedOff = mine.length ? String(mine[mine.length - 1].Status || '').toLowerCase() === 'human' : false;
const words = String(cfg.HandoffKeywords || '').toLowerCase().split(',').map(w => w.trim()).filter(Boolean);
const asksForHuman = words.some(w => msg.text.toLowerCase().includes(w));
return [{ json: { phone: msg.phone, text: msg.text, contactName: msg.contactName, messageId: msg.messageId, unsupported: msg.unsupported, history: history || 'This is the first message from this person.', turnCount: mine.length, handedOff, asksForHuman, needsHuman: handedOff || asksForHuman } }];

const s = $('Build Conversation State').first().json;
const reply = s.handedOff ? 'You are already in the queue for a team member - they will pick this up shortly.' : 'Of course, I am passing you to a team member now. They will reply here shortly.';
return { json: { phone: s.phone, reply, escalated: !s.handedOff } };

const s = $('Build Conversation State').first().json;
const raw = String($input.item.json.text || '').trim();
const reply = raw || 'Sorry, I had trouble with that one. Let me get a team member to reply.';
return { json: { phone: s.phone, reply, escalated: !raw } };

